{
  "name": "builder_all_pairs_gap_threshold_001",
  "intuition": "Filter pairwise preferences to only include pairs with a meaningful objective gap (configurable via extra['gap_threshold']) to reduce noisy/ambiguous comparisons and improve generalization.",
  "implementation_hint": {
    "expects": [
      "objective",
      "log_prob"
    ],
    "returns": "PrefBatch",
    "mode": "pairwise"
  },
  "code": "def generated_builder(feature_cache, extra):\n    objective = feature_cache['objective']\n    gap_threshold = extra.get('gap_threshold', 0.0)\n    diff = objective[:, :, None] - objective[:, None, :]\n    mask = diff < (-gap_threshold)\n    b_idx, winner_idx, loser_idx = mask.nonzero(as_tuple=True)\n    return PrefBatch(mode='pairwise', pair_idx=(b_idx, winner_idx, loser_idx), weight=None, meta={'builder': 'all_pairs_gap_threshold', 'gap_threshold': float(gap_threshold)})\n"
}

{
  "name": "rank_adjacent_pairs_002",
  "intuition": "Per instance, sort candidates by objective (lower is better) with deterministic index tie-breaking, then emit adjacent rank pairs so each better-ranked candidate is preferred over the next one, capped by a per-instance budget for efficiency.",
  "implementation_hint": {
    "expects": [
      "objective",
      "log_prob"
    ],
    "returns": "PrefBatch",
    "mode": "pairwise"
  },
  "code": "def generated_builder(feature_cache, extra):
    objective = feature_cache['objective']
    B, N = objective.shape
    device = objective.device

    # If we cannot form any pairs, return an empty-but-valid PrefBatch.
    if N < 2 or B == 0:
        empty = objective.new_empty((0,), dtype=torch.long, device=device)
        return PrefBatch(
            mode='pairwise',
            pair_idx=(empty, empty, empty),
            weight=None,
            meta={'builder': 'rank_adjacent_pairs', 'note': 'no_pairs_possible'}
        )

    # Read cap from extra without using Python builtins like int().
    max_pairs = extra.get('max_pairs_per_instance', 64)
    if max_pairs is None:
        max_pairs_per_instance = torch.tensor(64.0, device=device).long()
    else:
        if hasattr(max_pairs, 'item'):
            max_pairs = max_pairs.item()
        # Handle numbers and numeric strings robustly.
        if isinstance(max_pairs, str):
            try:
                max_pairs = float(max_pairs)
            except Exception:
                max_pairs = 64.0
        try:
            max_pairs_t = torch.tensor(max_pairs, device=device, dtype=torch.float32)
        except Exception:
            max_pairs_t = torch.tensor(64.0, device=device, dtype=torch.float32)
        # Clamp to sane range; ensure at least 1.
        max_pairs_per_instance = max_pairs_t.nan_to_num(nan=1.0, posinf=4096.0, neginf=1.0).clamp(min=1.0, max=4096.0).long()

    # Stable sort by objective, then by index for deterministic tie-breaking.
    idx = torch.arange(N, device=device)
    idx_expand = idx.view(1, N).expand(B, N)
    obj = objective

    # Scale objective to dominate index; index breaks ties deterministically.
    scale = obj.detach().abs().amax().clamp(min=torch.tensor(1.0, device=device)) + 1.0
    key = obj * (scale * (N + 1)) + idx_expand.to(obj.dtype)
    order = key.argsort(dim=1, stable=True)

    # Adjacent pairs: order[:, i] beats order[:, i+1]
    K = N - 1
    K_cap = max_pairs_per_instance.item()
    if K > K_cap:
        K = K_cap

    winners = order[:, :K].reshape(-1)
    losers = order[:, 1:K + 1].reshape(-1)

    b_idx = torch.arange(B, device=device).view(B, 1).expand(B, K).reshape(-1).to(torch.long)
    winner_idx = winners.to(torch.long)
    loser_idx = losers.to(torch.long)

    return PrefBatch(
        mode='pairwise',
        pair_idx=(b_idx, winner_idx, loser_idx),
        weight=None,
        meta={
            'builder': 'rank_adjacent_pairs',
            'max_pairs_per_instance': max_pairs_per_instance.item(),
            'pairing': 'adjacent_rank'
        }
    )"
}

{
  "name": "builder_all_pairs_gap_weight_001",
  "intuition": "Weight each preference by the objective gap so clearer wins contribute more signal while still using all ordered pairs; this can improve robustness when many near-ties add noise.",
  "implementation_hint": {
    "expects": [
      "objective",
      "log_prob"
    ],
    "returns": "PrefBatch",
    "mode": "pairwise"
  },
  "code": "def generated_builder(feature_cache, extra):\n    objective = feature_cache['objective']\n    mask = objective[:, :, None] < objective[:, None, :]\n    b_idx, winner_idx, loser_idx = mask.nonzero(as_tuple=True)\n    gap = (objective[b_idx, loser_idx] - objective[b_idx, winner_idx])\n    # Nonnegative weights; emphasize larger gaps while keeping small gaps > 0.\n    weight = gap.clamp(min=0) + 1e-6\n    return PrefBatch(mode='pairwise', pair_idx=(b_idx, winner_idx, loser_idx), weight=weight, meta={'builder': 'all_pairs_gap_weight', 'eps': 1e-6})\n"
}

