{
  "name": "loss_logsigmoid_consensus_clamped_v1",
  "intuition": "All parents share a stable pairwise preference core: encourage log_prob_w > log_prob_l via a clamped margin fed into -logsigmoid, optionally weighted, then averaged. Some variants also subtract a small detached cost gap (cost_b - cost_a), which is a safe way to bias preferences without backprop through costs. The consensus child keeps the proven clamped logsigmoid structure, uses a conservative mid-range scale, and conditionally incorporates the detached cost gap only when available to stay robust across batch schemas.",
  "pseudocode": "d = log_prob_w - log_prob_l; gap = detach(cost_b - cost_a) if present else 0; x = clamp(alpha*scale*d - cost_weight*gap, -20, 20); loss = -logsigmoid(x); if weight present: loss*=weight; return mean(loss)",
  "hyperparams": {
    "scale": 1.0,
    "cost_weight": 0.1,
    "clamp_min": -20.0,
    "clamp_max": 20.0
  },
  "operators_used": [
    "logsigmoid",
    "clamp"
  ],
  "code": "def generated_loss(batch, model_output, extra):\n    lpw = batch['log_prob_w']\n    lpl = batch['log_prob_l']\n    weight = batch.get('weight', None)\n\n    hp = extra.get('hyperparams', {}) if isinstance(extra, dict) else {}\n    alpha = float(extra.get('alpha', hp.get('alpha', 1.0))) if isinstance(extra, dict) else 1.0\n    scale = float(hp.get('scale', 1.0))\n    cost_weight = float(hp.get('cost_weight', 0.1))\n    clamp_min = float(hp.get('clamp_min', -20.0))\n    clamp_max = float(hp.get('clamp_max', 20.0))\n\n    d = lpw - lpl\n\n    gap = 0.0\n    if ('cost_a' in batch) and ('cost_b' in batch):\n        gap = (batch['cost_b'] - batch['cost_a']).detach()\n\n    x = alpha * scale * d - cost_weight * gap\n    x = ops.clamp(x, clamp_min, clamp_max)\n    loss = -ops.logsigmoid(x)\n\n    if weight is not None:\n        loss = loss * weight\n\n    return loss.mean()",
  "theoretical_basis": "Pairwise logistic (Bradley-Terry / preference) loss on log-prob differences, stabilized by clamping; optional detached cost-gap shaping adds a bias term without introducing gradients through external cost signals.",
  "implementation_hint": {
    "expects": {
      "batch": [
        "log_prob_w",
        "log_prob_l"
      ],
      "optional_batch": [
        "weight",
        "cost_a",
        "cost_b"
      ],
      "extra": [
        "alpha",
        "hyperparams"
      ]
    },
    "notes": "Uses only ops.clamp and ops.logsigmoid plus basic tensor ops; cost shaping is applied only if cost_a/cost_b exist and is detached."
  }
}

