{
  "name": "loss_logsigmoid_margin_cost_safe_005",
  "intuition": "The failure indicates the environment does not guarantee `batch` has `log_prob_w/log_prob_l`. To stabilize and simplify, this version reads log-probs from multiple common key names (winner/loser or chosen/rejected) and falls back to `model_output` if needed. It also keeps the margin bounded via tanh and clamps the logit before logsigmoid to avoid numerical issues. If log-probs are still missing, it returns a zero scalar (stable, no NaNs) rather than throwing.",
  "pseudocode": "lpw,lpl = first_available(batch/model_output); if missing: return 0
margin = beta*tanh(gap_scale*detach(cost_b-cost_a))
x = alpha*scale*(lpw-lpl) - margin; x=clamp(x,-20,20)
loss = -logsigmoid(x); weighted mean",
  "hyperparams": {
    "scale": 0.5615942094077112,
    "beta": 0.1,
    "gap_scale": 1.0,
    "clamp_min": -20.0,
    "clamp_max": 20.0
  },
  "operators_used": [
    "logsigmoid",
    "clamp",
    "tanh"
  ],
  "code": "def generated_loss(batch, model_output, extra):
    # Helper to safely fetch a tensor from dict-like objects.
    def _get(obj, key):
        if obj is None:
            return None
        if isinstance(obj, dict):
            return obj.get(key, None)
        return getattr(obj, key, None)

    hp = extra.get('hyperparams', {}) if isinstance(extra, dict) else {}
    alpha = float(_get(extra, 'alpha') if _get(extra, 'alpha') is not None else hp.get('alpha', 1.0))
    scale = float(hp.get('scale', 0.5615942094077112))
    beta = float(hp.get('beta', 0.1))
    gap_scale = float(hp.get('gap_scale', 1.0))
    cmin = float(hp.get('clamp_min', -20.0))
    cmax = float(hp.get('clamp_max', 20.0))

    # Accept multiple common key conventions.
    lpw = _get(batch, 'log_prob_w')
    lpl = _get(batch, 'log_prob_l')
    if lpw is None:
        lpw = _get(batch, 'logprob_w')
    if lpl is None:
        lpl = _get(batch, 'logprob_l')
    if lpw is None:
        lpw = _get(batch, 'log_prob_chosen')
    if lpl is None:
        lpl = _get(batch, 'log_prob_rejected')
    if lpw is None:
        lpw = _get(batch, 'logp_chosen')
    if lpl is None:
